#define S( a, b, val ) smoothstep( a, b, val )
#define sat( x ) clamp( x, 0., 1. )

float normalise( float zero, float one, float val ) {
    return sat( ( val - zero ) / ( one - zero ) );
}
float remap( float oldLower, float oldUpper, float newLower, float newUpper, float val ) {
    return normalise( oldLower, oldUpper, val ) * ( newUpper - newLower ) + newLower;
}

vec2 within( vec2 uv, vec4 rect ) {
    return ( uv - rect.xy ) / ( rect.zw - rect.xy );
}

vec4 brow( vec2 uv, float grimace ) {
    float y = uv.y;
    uv.y += uv.x * 1.1 -.3;
    uv.x -= .01;
    uv -= .5;

    vec2 shadowUV = uv;

    uv.y -= grimace / 3.;

    vec4 col = vec4( 0. );

    float blur = .15;

    float d1 = length( uv );
    float s1 = S( .45, .45 - blur, d1 );
    float d2 = length( uv - vec2( .1, -.2) *.7 );
    float s2 = S( .5, .5 - blur, d2 );

    float browMask = sat( s1 - s2 );
    float colMask = normalise( .7, .8, y );
    colMask *= S( .5, 2., browMask );
    vec4 browCol = mix( vec4( .4, .2, .2, 1. ), vec4( 1. ), colMask ); 

    shadowUV.y -= ( .15 * grimace );
    d1 = length( shadowUV );
    s1 = S( .45, .45 - blur, d1 );
    d2 = length( shadowUV - vec2( .1, -.2 ) * .7 );
    s2 = S( .5, .5 - blur, d2 );
    float shadowMask = sat( s1 - s2 );

    col = mix( col, vec4( 0., 0., 0., .1 ), S( .0, .9, shadowMask ) * 6.5 / ( grimace * 3. ) );

    col = mix( col, browCol, S( .2, .4, browMask ) );
    return col;
}

vec4 eye( vec2 uv, float side, vec2 m, float grimace ) {
    uv -= .75;
    vec4 col = vec4( 1., 1., 1., 1. );

    float d = length( uv );
    float eyePos = length( vec2( uv.x * side, uv.y ) - m * .3 );
    float irisPos = length( vec2( uv.x * side, uv.y ) - m * .35 );

    vec4 irisCol = vec4( .2, .8, .4, 1. );
    col = mix( col, irisCol, S( .4, .7, d ) * .6 );
    col.rgb *= 1. - S( .6, .7, d ) * .3 * sat( uv.y - uv.x );

    irisCol.rgb *= 1. + S( .41, .1, eyePos ) * .3;
    float pupilSize = .3 - ( grimace / 6. );
    irisCol.rgb = mix( irisCol.rgb, vec3( 0. ), S( pupilSize, pupilSize * .9 - .02, irisPos ) );

    uv.x *= side;
    float highlight = S( .16, .14, length( uv - vec2( -.25, .25 ) ) );
    highlight += S( .1, .07, length( uv - vec2( .15, -.15 ) ) );


    col.a = S( .7, .648, d );
    col.rgb = mix( col.rgb, vec3( 0. ), S( .44, .42, eyePos ) );
    col.rgb = mix( col.rgb, irisCol.rgb, S( .41, .36, eyePos ) );
    col.rgb = mix( col.rgb, vec3( 1. ), highlight ); 

    return col;
}

vec4 mouth( vec2 uv, float grimace ) {
    uv -= .5;
    vec4 col = vec4( .6, .2, .02, .5 );
    vec2 mouthMask = uv;

    grimace -= .5;
    uv.y -= uv.x * uv.x * 2.;
    mouthMask.y -=  mouthMask.x * mouthMask.x * 4. * grimace;
    mouthMask.y += .25 * grimace - .05;

    float d = length( uv );
    float md = length( mouthMask );

    col.a = S( .5, .45, md );
    col.rgb -= d * d; 

    float td = length( uv - vec2( 0., -.5 ) );
    vec3 toothCol = vec3( 1. ) * S( .6, .35, md );
    col.rgb = mix( col.rgb, toothCol, S( .4, .37, td ) );


    td = length( uv - vec2( .0, .9 ) );
    float tgd = length( vec2( abs( uv.x ) + .25, uv.y ) - vec2( .4, .3 ) );
    vec3 tongueCol = vec3( .9, .4, .4 );
    tongueCol.rgb = mix( tongueCol.rgb, vec3( 0. ), S( .6, .3, d ) * .25 );
    tongueCol.rgb = mix( tongueCol.rgb, vec3( 0. ), S( .2, .6, md ) * .5 );
    col.rgb = mix( col.rgb, tongueCol, S( .29, .27, tgd ) );

    col.rgb = mix( col.rgb, toothCol, S( .4, .37, td ) );

    return col;
}

vec4 head( vec2 uv, float side ) {
    vec4 col = vec4( .98, .76, .08, 1. );

    float d = length( uv );

    col.a = S( .75, .74, d );

    float edgeShade = normalise( .3, 1. , d );
    edgeShade *= edgeShade;
    col.rgb *= 1. - edgeShade;

    col.rgb = mix( col.rgb, vec3( .6, .3, .1 ), S( .72, .73, d ) );

    float highlight = S( .62, .61, d ) * .9;
    highlight *= sat( uv.y + .2 );
    highlight *= S( .23, .28, length( uv - vec2( .28 + (-.02 * side ), .18 ) ) );

    col.rgb = mix( col.rgb, vec3( 1. ), highlight );

    d = length( uv - vec2( .4, -.2 ) );
    float cheek = S( .3, .01, d ) * .4;
    cheek *= S( .27, .26, d );
    col.rgb = mix( col.rgb, vec3( 1., .1, .1 ), cheek );
    return col;
}

vec4 smiley( vec2 uv, vec2 m, float grimace ) {

    vec4 mouth = mouth( within( uv, vec4( -.45, -.1, .45, -.45 ) ), grimace );
    vec4 col = vec4( 0.4, 0.1, 0.3, 1. );
    float side = sign( uv.x );
    uv.x = abs( uv.x );
    vec4 head = head( uv, side );
    vec4 eye = eye( within( uv, vec4( .03, -.1, .37, .25 ) ), side, m, grimace );
    vec4 brow = brow( within( uv, vec4( .03, .3, .6, .65 ) ), grimace );

    col = mix( col, head, head.a );
    col = mix( col, eye, eye.a );
    col = mix( col, mouth, mouth.a );
    col = mix( col, brow, brow.a );
    return col;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord / iResolution.xy;
    uv -= .5;
    uv *= 2.;
    uv.x *= iResolution.x / iResolution.y;

    vec2 m = iMouse.xy / iResolution.xy;
    if ( iMouse.xy == vec2( 0. ) ) {
        m = vec2( 0.91 );
    }
    m -= .5;
    m *= 2.;

    float inverse = 1. - length( uv );
    uv += inverse * m * .3;

    float grimace = length( 1. - abs( m ) );
    fragColor = smiley( uv, m, grimace );
}
